def test_video_renderer_creates_dual_layer_clips():
    """Test that VideoRenderer creates normal + highlight layers for each verse."""
    renderer = VideoRenderer(resolution=(640, 360), fps=30)

    # Create mock data
    verses = [
        ("Deuteronomy 32:1", "הַאֲזִ֥ינוּ הַשָּׁמַ֖יִם וַאֲדַבֵּ֑רָה"),
        ("Deuteronomy 32:2", "יַעֲרֹ֤ף כַּמָּטָר֙ לִקְחִ֔י"),
    ]

    pasuk_alignments = [
        PasukAlignment(
            alignment_run_id=1,
            reference="Deuteronomy 32:1",
            hebrew_text="הַאֲזִ֥ינוּ הַשָּׁמַ֖יִם וַאֲדַבֵּ֑רָה",
            verse_order=1,
            start_time=0.0,
            end_time=4.2,
            confidence=0.95,
        ),
        PasukAlignment(
            alignment_run_id=1,
            reference="Deuteronomy 32:2",
            hebrew_text="יַעֲרֹ֤ף כַּמָּטָר֙ לִקְחִ֔י",
            verse_order=2,
            start_time=4.2,
            end_time=7.8,
            confidence=0.92,
        ),
    ]

    alignment_run = AlignmentRun(
        alya_audio_id=1,
        alignment_quality=0.93,
        verse_count=2,
    )

    # Create clips
    clips = renderer._create_text_clips(
        alignment_run=alignment_run,
        verses=verses,
        audio_duration=10.0,
        pasuk_alignments=pasuk_alignments,
    )

    # Should have 2 verses × 2 layers = 4 clips
    assert len(clips) == 4, f"Expected 4 clips (2 verses × 2 layers), got {len(clips)}"

    # Check that highlight clips have correct timing
    # Clips are ordered: [normal1, highlight1, normal2, highlight2]
    highlight1 = clips[1]
    highlight2 = clips[3]

    assert highlight1.start == 0.0, "First highlight should start at 0.0s"
    assert highlight1.end == 4.2, "First highlight should end at 4.2s"
    assert highlight2.start == 4.2, "Second highlight should start at 4.2s"
    assert highlight2.end == 7.8, "Second highlight should end at 7.8s"


