def test_render_verses_tall_canvas_creates_tall_image():
    """Test that render_verses_tall_canvas creates a tall canvas with all verses."""
    verses = [
        ("Deuteronomy 32:1", "הַאֲזִ֥ינוּ הַשָּׁמַ֖יִם וַאֲדַבֵּ֑רָה"),
        ("Deuteronomy 32:2", "יַעֲרֹ֤ף כַּמָּטָר֙ לִקְחִ֔י"),
        ("Deuteronomy 32:3", "כִּ֛י שֵׁ֥ם יְהוָ֖ה אֶקְרָ֑א"),
    ]

    canvas, verse_positions = render_verses_tall_canvas(
        verses=verses,
        width=1280,
        font_path="/System/Library/Fonts/ArialHB.ttc",
        font_size=40,
        text_color="#FFFFFF",
        verse_spacing=120,
        top_margin=40,
    )

    # Canvas should be tall enough for all verses
    expected_height = 40 + (3 * 120)  # top_margin + (num_verses * spacing)
    assert canvas.size == (1280, expected_height), f"Canvas size should be 1280x{expected_height}"
    assert canvas.mode == "RGBA", "Canvas should be RGBA for transparency"

    # Should have Y positions for all verses
    assert len(verse_positions) == 3, "Should have positions for all 3 verses"
    assert verse_positions[0] == 40, "First verse should be at top_margin"
    assert verse_positions[1] == 160, "Second verse should be at top_margin + spacing"
    assert verse_positions[2] == 280, "Third verse should be at top_margin + 2*spacing"


def test_scrolling_clips_uses_scrolling_for_many_verses():
    """Test that VideoRenderer uses scrolling layout for > 6 verses."""
    renderer = VideoRenderer(resolution=(1280, 720), fps=30)

    # Create 7 verses (triggers scrolling)
    verses = [(f"Verse {i}", f"Text {i}") for i in range(1, 8)]
    pasuk_alignments = [
        PasukAlignment(
            alignment_run_id=1,
            reference=f"Verse {i}",
            hebrew_text=f"Text {i}",
            verse_order=i,
            start_time=i * 5.0,
            end_time=(i + 1) * 5.0,
            confidence=0.95,
        )
        for i in range(1, 8)
    ]

    alignment_run = AlignmentRun(
        alya_audio_id=1,
        alignment_quality=0.93,
        verse_count=7,
    )

    clips = renderer._create_text_clips(
        alignment_run=alignment_run,
        verses=verses,
        audio_duration=50.0,
        pasuk_alignments=pasuk_alignments,
    )

    # Should create 1 normal scrolling layer + 7 highlight layers = 8 clips
    assert len(clips) == 8, f"Expected 8 clips (1 normal + 7 highlights), got {len(clips)}"

    # First clip should be the scrolling normal layer
    normal_clip = clips[0]
    assert normal_clip.duration == 50.0, "Normal clip duration should match audio"

    # Check that position function exists (indicates scrolling)
    assert hasattr(normal_clip, 'pos'), "Normal clip should have position function for scrolling"


